:root {
  --ink: #1a1208;
  --parchment: #d9c99a;
  --parchment-dark: #c4ae7d;
  --parchment-mid: #e8dbb8;
  --steel: #4a5a6b;
  --steel-light: #7a90a4;
  --rust: #8b3a1e;
  --olive: #5c6b2e;
  --navy: #1c2d45;
  --amber: #b87a18;
  --amber-light: #d4a030;
  --white-off: #f2ead4;
  --border-heavy: #7a6030;
}

article.watch-log {
  background-color: var(--parchment-mid);
  border: 3px solid var(--border-heavy);
  border-radius: 4px;
  width: 464px;
  padding: 10px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.log-header {
  display: flex;
  align-items: center;
  gap: 10px;
  border-bottom: 2px solid var(--border-heavy);
  padding-bottom: 8px;
}

.vessel-badge {
  background-color: var(--navy);
  color: var(--amber-light);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.1em;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 2px solid var(--amber);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.header-text {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.vessel-name {
  font-size: 17px;
  font-weight: 900;
  color: var(--navy);
  letter-spacing: 0.12em;
  line-height: 1;
  margin: 0;
}

.vessel-class {
  font-size: 10px;
  color: var(--steel);
  letter-spacing: 0.06em;
  margin: 0;
  font-weight: 600;
}

.depth-gauge {
  display: flex;
  flex-direction: column;
  align-items: center;
  background-color: var(--navy);
  border-radius: 4px;
  padding: 4px 10px;
  gap: 1px;
}

.gauge-label {
  font-size: 8px;
  color: var(--steel-light);
  letter-spacing: 0.15em;
  font-weight: 700;
}

.gauge-value {
  font-size: 15px;
  font-weight: 900;
  color: var(--amber-light);
  line-height: 1;
}

.watch-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 5px;
}

.watch-cell {
  background-color: var(--parchment);
  border: 1px solid var(--parchment-dark);
  border-radius: 3px;
  padding: 5px 7px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.cell-label {
  font-size: 8px;
  color: var(--steel);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.cell-value {
  font-size: 11px;
  font-weight: 800;
  color: var(--ink);
  line-height: 1.2;
}

.sightings {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.sightings-title {
  font-size: 9px;
  font-weight: 800;
  color: var(--rust);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  margin: 0;
  border-bottom: 1px dashed var(--parchment-dark);
  padding-bottom: 3px;
}

.sighting-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.sighting-row {
  display: flex;
  align-items: center;
  gap: 7px;
  background-color: var(--white-off);
  border: 1px solid var(--parchment-dark);
  border-radius: 3px;
  padding: 4px 7px;
}

.sight-time {
  font-size: 10px;
  font-weight: 800;
  color: var(--navy);
  letter-spacing: 0.05em;
  flex-shrink: 0;
  min-width: 34px;
}

.sight-type {
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 2px 5px;
  border-radius: 2px;
  flex-shrink: 0;
}

.sight-type.merchant {
  background-color: var(--amber);
  color: var(--white-off);
}

.sight-type.destroyer {
  background-color: var(--rust);
  color: var(--white-off);
}

.sight-type.neutral {
  background-color: var(--olive);
  color: var(--white-off);
}

.sight-desc {
  font-size: 10px;
  color: var(--steel);
  font-weight: 500;
  line-height: 1.3;
}

.log-footer {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  border-top: 2px solid var(--border-heavy);
  padding-top: 6px;
}

.status-row {
  display: flex;
  align-items: center;
  gap: 7px;
}

.status-label {
  font-size: 9px;
  color: var(--steel);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.status-badge {
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  padding: 2px 7px;
  border-radius: 2px;
  background-color: var(--navy);
  color: var(--amber-light);
  border: 1px solid var(--amber);
}

.signature-row {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 1px;
}

.sig-line {
  font-size: 12px;
  color: var(--ink);
  letter-spacing: 0.05em;
}

.sig-label {
  font-size: 8px;
  color: var(--steel);
  font-weight: 700;
  letter-spacing: 0.1em;
}
